 return [json.loads(line) for line in Path(path).read_text().splitlines()]
now=datetime.now(timezone.utc).isoformat()
bundle=dict(artifacts={}, evidence=[], reviews=[], findings=[])
sources={Path(r[\"locator\"]).name[:2]:r for r in rows(\"audit-collection/evidence.jsonl\") if r[\"kind\"]==\"content\"}
