 \"01\": {\"claim-sources\":(3,14),\"entity-record\":(3,14),\"audience-context\":(16,24)},
 \"02\": {\"claim-sources\":(3,21),\"audience-context\":(1,21)},
 \"03\": {\"claim-sources\":(3,16),\"entity-record\":(3,16),\"inventory-map\":(3,19),\"audience-context\":(3,19)},
 \"04\": {\"claim-sources\":(3,19),\"question-set\":(8,13),\"audience-context\":(6,18)}
}
ids={}
for num,s in sources.items():
 ids[num]={\"content\":s[\"evidenceId\"]}
 lines=s[\"value\"].splitlines(keepends=True)
 for kind,(lo,hi) in {**refs[num],\"extracted-text\":(1,len(lines))}.items():
  key=num+\"-\"+kind
  locator=Path(s[\"locator\"]).name+f\":{lo}-{hi}\"
  value=\"\".join(lines[lo-1:hi])
  artifact=\"evidence/\"+key+\".txt\"
  rec={**s,\"evidenceId\":key,\"kind\":kind,\"locator\":locator,\"artifact\":artifact,\"value\":value,\"collectedAt\":now,\"sourceEvidenceIds\":[s[\"evidenceId\"]],\"snapshotHash\":hashlib.sha256(value.encode()).hexdigest(),\"byteLength\":len(value.encode()),\"limitations\":[\"Attributed excerpt from the supplied synthetic dossier. Live behavior was unverified.\"]}
  ids[num][kind]=key
  bundle[\"evidence\"].append(rec)
  bundle[\"artifacts\"][artifact]=value
registry={r[\"ruleId\"]:r for r in json.loads(Path(\".agents/skills/content-search-audit/rules/core.json\").read_text())[\"rules\"]}
def evidence(n,rules):
 return sorted({ids[n][k] for r in rules for k in registry[r][\"requiredEvidence\"]})
