 bundle[\"reviews\"].append(dict(itemId=sources[n][\"itemId\"],ruleId=r,status=status,reason=reason,evidenceIds=evidence(n,[r]),reviewer=\"Codex offline dossier review\",reviewedAt=now))
def finding(n,i,title,rules,remediation,verification,severity=\"medium\"):
 bundle[\"findings\"].append(dict(findingId=i,title=title,affectedItemIds=[sources[n][\"itemId\"]],ruleIds=rules,dimensions=list(dict.fromkeys(r.split(\"-\")[0] for r in rules)),evidenceIds=evidence(n,rules),severity=severity,confidence=\"high\",classification=\"observed\",remediation=remediation,verification=verification,ownerRole=\"Content or reporting owner\",effort=\"small\"))
comparison=[\"quality-claims\",\"aeo-answer-evidence\",\"aio-entity-consistency\"]
for r in comparison:
 review(\"01\",r,\"fail\",\"The decision-facing SSO and all-billing assertions in /compare conflict with the supplied November 2026 US records. The separate monthly caption agrees with the monthly records.\")
finding(\"01\",\"fir-sso\",\"Fir SSO denial contradicts the supplied Enterprise documentation\",comparison,\"State Enterprise SAML SSO and the 20 paid-seat minimum. Treat other plans as unspecified in the supplied records.\",\"Check the final claim against lines 12–14, retaining plan, SAML and seat minimum.\")
finding(\"01\",\"billing-comparison\",\"Universal price advantage reverses on annual billing\",comparison,\"Show the supplied monthly and annual-billed rates independently with US, USD, pre-tax and time scope.\",\"Compare both revised billing rows with lines 3–10 and confirm monthly Cedar advantage is USD 3 and annual Fir advantage is USD 1 per seat per month equivalent.\")
review(\"02\",\"quality-claims\",\"fail\",\"Draft A mixes monthly spend with one week of conversion data; Draft B asserts a total and tracking rate without evidence. The aligned first-week caption is supported.\")
finding(\"02\",\"conversion-window\",\"October cost per conversion uses mismatched windows\",[\"quality-claims\"],\"Use the aligned October 1–7 cost per completed conversion and label October 8–31 unmeasured.\",\"Verify same campaign, currency, dates and conversion definition in numerator and denominator before recomputing.\")
finding(\"02\",\"referral-extrapolation\",\"Tracked AI referrals are extrapolated without an attribution model\",[\"quality-claims\"],\"Report the 15 identified October sessions, unknown origin of other sessions, and unavailable total AI influence.\",\"Match the reported count to the referral record and ensure no multiplier, causal or conversion assertion is implied.\")
south=[\"quality-claims\",\"quality-task-fit\",\"aeo-answer-evidence\",\"aio-entity-consistency\",\"portfolio-contradictions\"]
for r in south:
 review(\"03\",r,\"fail\",\"The complete current South policy passage conflicts with the approved South policy. North matches its current policy. The clearly labeled 2024 archive describes a separate contract.\")
finding(\"03\",\"south-policy\",\"South current page states the wrong service level\",south,\"Replace the copied service rule with next-business-day delivery only and retain region and archive distinctions.\",\"Compare revised South and North passages with approved policy, and confirm the archive remains labeled 2024 and links to both current pages.\",\"high\")
